insert into public.teaching_translations(id,teaching_id,language,slug,title,excerpt,article_content,youtube_video_id,status,published_at) values (md5('development:sample-repentance')::uuid,'sample-repentance','en','what-is-repentance','What is repentance?','Explore what repentance means in the Orthodox Christian life and why it is central to our journey toward God.','{"version":1,"sections":[{"id":"introduction","heading":"Introduction","paragraphs":["Repentance is a turning of the heart toward God. It invites us to examine our lives, acknowledge our failings, and seek renewal through His grace."]},{"id":"watch-the-teaching","heading":"Watch the teaching","video":{"title":"What is repentance?"}},{"id":"a-life-of-repentance","heading":"A life of repentance","paragraphs":["This sample teaching explores how prayer, confession, and daily choices can shape a life of repentance."]}]}'::jsonb,null,'draft',null) on conflict (teaching_id,language) do nothing;
insert into public.teaching_translations(id,teaching_id,language,slug,title,excerpt,article_content,youtube_video_id,status,published_at) values (md5('development:sample-sacraments')::uuid,'sample-sacraments','en','understanding-the-sacraments','Understanding the sacraments','A clear introduction to the sacraments, their meaning, and their role in the life of the Church.','{"version":1,"sections":[{"id":"introduction","heading":"Introduction","paragraphs":["A clear introduction to the sacraments, their meaning, and their role in the life of the Church."]},{"id":"reflection","heading":"Reflection and daily life","paragraphs":["This draft invites readers to consider this topic through prayer, careful study, and conversation with their priest. The final teaching and supporting sources will be supplied and reviewed by the client."]}]}'::jsonb,null,'draft',null) on conflict (teaching_id,language) do nothing;
insert into public.teaching_translations(id,teaching_id,language,slug,title,excerpt,article_content,youtube_video_id,status,published_at) values (md5('development:sample-fathers')::uuid,'sample-fathers','en','learning-from-the-church-fathers','Learning from the Church Fathers','Discover how the teachings of the Church Fathers guide us in faith, life, and discernment today.','{"version":1,"sections":[{"id":"introduction","heading":"Introduction","paragraphs":["Discover how the teachings of the Church Fathers guide us in faith, life, and discernment today."]},{"id":"reflection","heading":"Reflection and daily life","paragraphs":["This draft invites readers to consider this topic through prayer, careful study, and conversation with their priest. The final teaching and supporting sources will be supplied and reviewed by the client."]}]}'::jsonb,null,'draft',null) on conflict (teaching_id,language) do nothing;
insert into public.teaching_translations(id,teaching_id,language,slug,title,excerpt,article_content,youtube_video_id,status,published_at) values (md5('development:sample-repentance-am')::uuid,'sample-repentance','am','repentance-am','ንስሐ ምንድን ነው?','ንስሐ በኦርቶዶክስ ክርስቲያናዊ ሕይወት ምን ማለት እንደሆነና ወደ እግዚአብሔር በምናደርገው ጉዞ ያለውን አስፈላጊነት ይወቁ።','{"version":1,"sections":[{"id":"introduction","heading":"መግቢያ","paragraphs":["ንስሐ ልብን ወደ እግዚአብሔር መመለስ ነው። ሕይወታችንን እንድንመረምር፣ ስህተታችንን እንድንቀበልና በጸጋው እንድንታደስ ይጋብዘናል።"]},{"id":"a-life-of-repentance","heading":"የንስሐ ሕይወት","paragraphs":["ይህ የናሙና ትምህርት ጸሎት፣ ንስሐና የዕለት ተዕለት ምርጫዎች የንስሐ ሕይወትን እንዴት እንደሚቀርጹ ያስተዋውቃል።"]}]}'::jsonb,null,'draft',null) on conflict (teaching_id,language) do nothing;
insert into public.teaching_translations(id,teaching_id,language,slug,title,excerpt,article_content,youtube_video_id,status,published_at) values (md5('development:sample-tradition')::uuid,'sample-tradition','en','tradition','Faith and sacred tradition','Explore the relationship between faith and sacred tradition in the life of the Church.','{"version":1,"sections":[{"id":"introduction","heading":"Introduction","paragraphs":["Explore the relationship between faith and sacred tradition in the life of the Church."]},{"id":"reflection","heading":"Reflection and daily life","paragraphs":["This draft invites readers to consider this topic through prayer, careful study, and conversation with their priest. The final teaching and supporting sources will be supplied and reviewed by the client."]}]}'::jsonb,null,'draft',null) on conflict (teaching_id,language) do nothing;
insert into public.teaching_translations(id,teaching_id,language,slug,title,excerpt,article_content,youtube_video_id,status,published_at) values (md5('development:sample-confession')::uuid,'sample-confession','en','preparing-for-confession','Preparing for confession','Practical guidance on how to prepare for confession and approach this sacrament with a humble and sincere heart.','{"version":1,"sections":[{"id":"introduction","heading":"Introduction","paragraphs":["Practical guidance on how to prepare for confession and approach this sacrament with a humble and sincere heart."]},{"id":"reflection","heading":"Reflection and daily life","paragraphs":["This draft invites readers to consider this topic through prayer, careful study, and conversation with their priest. The final teaching and supporting sources will be supplied and reviewed by the client."]}]}'::jsonb,null,'draft',null) on conflict (teaching_id,language) do nothing;
insert into public.teaching_translations(id,teaching_id,language,slug,title,excerpt,article_content,youtube_video_id,status,published_at) values (md5('development:sample-sacraments-am')::uuid,'sample-sacraments','am','sacraments-am','ምሥጢራትን መረዳት','ስለ ምሥጢራት፣ ትርጉማቸውና በቤተ ክርስቲያን ሕይወት ስላላቸው ድርሻ መግቢያ ትምህርት።','{"version":1,"sections":[{"id":"introduction","heading":"መግቢያ","paragraphs":["ስለ ምሥጢራት፣ ትርጉማቸውና በቤተ ክርስቲያን ሕይወት ስላላቸው ድርሻ መግቢያ ትምህርት።"]},{"id":"reflection","heading":"ማሰላሰልና የዕለት ተዕለት ሕይወት","paragraphs":["ይህ ረቂቅ ርዕሱን በጸሎት፣ በጥናትና ከካህን ጋር በውይይት እንድናሰላስል ይጋብዘናል። የመጨረሻው ትምህርትና ምንጮች በደንበኛው ይቀርባሉ።"]}]}'::jsonb,null,'draft',null) on conflict (teaching_id,language) do nothing;
insert into public.teaching_translations(id,teaching_id,language,slug,title,excerpt,article_content,youtube_video_id,status,published_at) values (md5('development:sample-fathers-am')::uuid,'sample-fathers','am','fathers-am','ከቤተ ክርስቲያን አባቶች መማር','የቤተ ክርስቲያን አባቶች ትምህርቶች በእምነት፣ በሕይወትና በማስተዋል እንዴት እንደሚመሩን ይወቁ።','{"version":1,"sections":[{"id":"introduction","heading":"መግቢያ","paragraphs":["የቤተ ክርስቲያን አባቶች ትምህርቶች በእምነት፣ በሕይወትና በማስተዋል እንዴት እንደሚመሩን ይወቁ።"]},{"id":"reflection","heading":"ማሰላሰልና የዕለት ተዕለት ሕይወት","paragraphs":["ይህ ረቂቅ ርዕሱን በጸሎት፣ በጥናትና ከካህን ጋር በውይይት እንድናሰላስል ይጋብዘናል። የመጨረሻው ትምህርትና ምንጮች በደንበኛው ይቀርባሉ።"]}]}'::jsonb,null,'draft',null) on conflict (teaching_id,language) do nothing;
insert into public.teaching_translations(id,teaching_id,language,slug,title,excerpt,article_content,youtube_video_id,status,published_at) values (md5('development:sample-tradition-am')::uuid,'sample-tradition','am','tradition-am','እምነትና ቅዱስ ትውፊት','በቤተ ክርስቲያን ሕይወት ውስጥ በእምነትና በቅዱስ ትውፊት መካከል ያለውን ግንኙነት ይወቁ።','{"version":1,"sections":[{"id":"introduction","heading":"መግቢያ","paragraphs":["በቤተ ክርስቲያን ሕይወት ውስጥ በእምነትና በቅዱስ ትውፊት መካከል ያለውን ግንኙነት ይወቁ።"]},{"id":"reflection","heading":"ማሰላሰልና የዕለት ተዕለት ሕይወት","paragraphs":["ይህ ረቂቅ ርዕሱን በጸሎት፣ በጥናትና ከካህን ጋር በውይይት እንድናሰላስል ይጋብዘናል። የመጨረሻው ትምህርትና ምንጮች በደንበኛው ይቀርባሉ።"]}]}'::jsonb,null,'draft',null) on conflict (teaching_id,language) do nothing;
