insert into public.teaching_translations(id,teaching_id,language,slug,title,excerpt,article_content,youtube_video_id,status,published_at) values (md5('development:sample-confession-am')::uuid,'sample-confession','am','confession-am','ለንስሐ መዘጋጀት','ለንስሐ በትሕትናና በቅን ልቦና ስለ መዘጋጀት የትምህርት ናሙና።','{"version":1,"sections":[{"id":"introduction","heading":"መግቢያ","paragraphs":["ለንስሐ በትሕትናና በቅን ልቦና ስለ መዘጋጀት የትምህርት ናሙና።"]},{"id":"reflection","heading":"ማሰላሰልና የዕለት ተዕለት ሕይወት","paragraphs":["ይህ ረቂቅ ርዕሱን በጸሎት፣ በጥናትና ከካህን ጋር በውይይት እንድናሰላስል ይጋብዘናል። የመጨረሻው ትምህርትና ምንጮች በደንበኛው ይቀርባሉ።"]}]}'::jsonb,null,'draft',null) on conflict (teaching_id,language) do nothing;
insert into public.teaching_translations(id,teaching_id,language,slug,title,excerpt,article_content,youtube_video_id,status,published_at) values (md5('development:sample-baptism-am')::uuid,'sample-baptism','am','baptism-am','ስለ ጥምቀት መግቢያ','ስለ ጥምቀትና ስለ ቤተ ክርስቲያን ሕይወት የትምህርት ናሙና።','{"version":1,"sections":[{"id":"introduction","heading":"መግቢያ","paragraphs":["ስለ ጥምቀትና ስለ ቤተ ክርስቲያን ሕይወት የትምህርት ናሙና።"]},{"id":"reflection","heading":"ማሰላሰልና የዕለት ተዕለት ሕይወት","paragraphs":["ይህ ረቂቅ ርዕሱን በጸሎት፣ በጥናትና ከካህን ጋር በውይይት እንድናሰላስል ይጋብዘናል። የመጨረሻው ትምህርትና ምንጮች በደንበኛው ይቀርባሉ።"]}]}'::jsonb,null,'draft',null) on conflict (teaching_id,language) do nothing;
